import{_ as e,o as a,c as r,aj as d}from"./chunks/framework.m090XgxO.js";const u=JSON.parse('{"title":"XiHan.UI 视图组件","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md","lastUpdated":1789199966000}'),o={name:"introduction.md"};function n(i,t,c,s,h,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="xihan-ui-视图组件" tabindex="-1">XiHan.UI 视图组件 <a class="header-anchor" href="#xihan-ui-视图组件" aria-label="Permalink to &quot;XiHan.UI 视图组件&quot;">​</a></h1><p>XiHan.UI 是一套<strong>框架无关</strong>的组件库：状态机与无障碍逻辑沉在无头内核里，每个前端框架只得到一层薄适配器。</p><p>当前提供 <strong>128 个组件</strong>，每个组件都有无头内核、Vue 组件、React 组件与自定义元素；127 个视觉组件另有默认皮肤，renderless Hotkeys 不伪造视觉层。各层同源，行为由内核唯一定义，三个适配器负责接入各自的渲染与事件机制。</p><h2 id="它和常见组件库有什么不一样" tabindex="-1">它和常见组件库有什么不一样 <a class="header-anchor" href="#它和常见组件库有什么不一样" aria-label="Permalink to &quot;它和常见组件库有什么不一样&quot;">​</a></h2><p>大多数组件库把「行为」和「某个框架的组件模型」焊在一起：换框架就得整套重写，而无障碍与键盘交互是最容易在重写中丢掉的部分。XiHan.UI 把这层拆开：</p><table tabindex="0"><thead><tr><th>层</th><th>包</th><th>职责</th></tr></thead><tbody><tr><td>适配器</td><td><code>@xihan-ui/vue</code>、<code>@xihan-ui/react</code>、<code>@xihan-ui/web-components</code></td><td>将同一份属性和行为接到各自宿主</td></tr><tr><td>无头内核</td><td><code>@xihan-ui/headless</code></td><td>解剖、状态机与 <code>connect</code></td></tr><tr><td>原语</td><td><code>@xihan-ui/core</code>、<code>position</code>、<code>motion</code>、<code>pointer</code></td><td>运行时、定位、动效与指针会话</td></tr><tr><td>表现</td><td><code>@xihan-ui/tokens</code>、<code>@xihan-ui/styles</code></td><td>共享令牌与纯 CSS 皮肤</td></tr></tbody></table><p>由此带来四条可以直接兑现的性质：</p><ul><li><strong>同一份行为，三种宿主。</strong> Vue、React 与自定义元素共享状态机和 <code>connect</code>；文档站提供对应框架示例，覆盖情况由示例门禁核对。</li><li><strong>样式与逻辑解耦。</strong> 皮肤只认 <code>data-scope</code> / <code>data-part</code> / <code>data-*</code> 状态属性，不认框架，也不认类名。整包换皮肤不用碰一行 JS。</li><li><strong>无障碍是判据，不是口号。</strong> 每个组件都有一份机读的<strong>键盘规格表</strong>（共 535 条），它同时是测试的分母：用例少覆盖一条即判套件失败。</li><li><strong>依赖面收得很紧。</strong> 全部库包的运行时第三方依赖只有一个（<code>@internationalized/date</code>，仅日期族使用）。定位、代码着色、Web Components 响应式基类都是自研。</li></ul><h2 id="从哪儿开始" tabindex="-1">从哪儿开始 <a class="header-anchor" href="#从哪儿开始" aria-label="Permalink to &quot;从哪儿开始&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你想做的事</th><th>去这里</th></tr></thead><tbody><tr><td>先看清楚整体是怎么搭的</td><td><a href="./overview">架构总览</a></td></tr><tr><td>把它接进现有项目</td><td><a href="./installation">安装与接入</a></td></tr><tr><td>写出第一个能跑的组件</td><td><a href="./quickstart">快速上手</a></td></tr><tr><td>查某个组件有哪些部件、支持哪些按键</td><td><a href="./components/">组件总览</a></td></tr><tr><td>改主题、改皮肤</td><td><a href="./guide/theme">设计令牌与主题</a>、<a href="./guide/styling">皮肤与样式分层</a></td></tr><tr><td>用 Vue / React / 原生自定义元素</td><td><a href="./adapters/vue">Vue 适配器</a>、<a href="./adapters/react">React 适配器</a>、<a href="./adapters/web-components">Web Components 适配器</a></td></tr><tr><td>做 AI 对话界面</td><td><a href="./guide/ai">AI 协议内核</a></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>源码仓库：<a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">Gitee</a> · <a href="https://gitcode.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitCode</a></li><li>同生态的另外两个仓库：<a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.Framework 开发框架</a>、<a href="https://basicapp.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.BasicApp 基础应用</a></li></ul><div class="tip custom-block"><p class="custom-block-title">与 XiHan.BasicApp 的关系</p><p>XiHan.BasicApp 的前端建在 XiHan.UI 之上——自 BasicApp v4.0.0 起整体用这套库重建，是组件库在真实业务里的第一个大体量消费方。BasicApp 的前端约定请看<a href="https://basicapp.docs.xihanfun.com/frontend/introduction" target="_blank" rel="noreferrer">基础应用前端手册</a>。</p></div>',13)])])}const f=e(o,[["render",n]]);export{u as __pageData,f as default};
